"""Build the authored debugging bank. Each row is a distinct failure scenario.

The final private diagnosis is for content QA; learners receive only the failure
brief and buggy code. These are reasoning missions, not executed test claims.
Difficulty is assigned per scenario, never by changing numbers or identifiers.
"""
import json
from pathlib import Path

ITEMS = []
LANGUAGES = {
    **{x: x for x in ('python','javascript','java','typescript','c','cpp','rust','go','csharp','ruby','html','css')},
    'python-django':'python','python-fastapi':'python','python-flask':'python',
    **{f'spring-{x}':'java' for x in ('boot','core','data','mvc','security','testing')},
    **{x:'css' for x in ('bootstrap','bulma','sass','shadcn','tailwind')},
    'embedded-c':'c','embedded-python':'python',
}
LEVELS = ('easy','medium','hard','expert','extreme')


def add(subject, rows, levels=None, node_ids=()):
    for n, (title, code, failure, goal, diagnosis) in enumerate(rows):
        ITEMS.append(dict(language=LANGUAGES[subject], subject=subject,
                          difficulty=(levels[n] if levels else LEVELS[n // 2]),
                          title=title, code=code, failure=failure, goal=goal,
                          node_ids=[f'{LANGUAGES[subject]}:{node}' for node in node_ids],
                          private_solution=diagnosis,
                          code_language=('html' if LANGUAGES[subject] == 'css' and code.lstrip().startswith('<') else LANGUAGES[subject])))


